patches.repl:
ul { font-family: system-ui, sans-serif; font-size: 15px; line-height: 1.7; }
    .tablewrap { overflow-x: auto; }
    table { border-collapse: collapse; width: 100%; font-family: system-ui, sans-serif; font-size: 14px; line-height: 1.5; margin: 12px 0; }
    th, td { border: 1px solid #2a2a3a; padding: 6px 8px; text-align: left; vertical-align: top; }
    th { color: #e8d5a3; background: #12121e; }
    code { font-size: 13px; }
